// HasRefunds applies the HasEdge predicate on the "refunds" edge.
func HasRefunds() predicate.SiteOrder {
	return predicate.SiteOrder(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, RefundsTable, RefundsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRefundsWith applies the HasEdge predicate on the "refunds" edge with a given conditions (other predicates).
func HasRefundsWith(preds ...predicate.SiteRefund) predicate.SiteOrder {
	return predicate.SiteOrder(func(s *sql.Selector) {
		step := newRefundsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasUser applies the HasEdge predicate on the "user" edge.
func HasUser() predicate.SiteOrder {
	return predicate.SiteOrder(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, UserTable, UserColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUserWith applies the HasEdge predicate on the "user" edge with a given conditions (other predicates).
func HasUserWith(preds ...predicate.User) predicate.SiteOrder {
	return predicate.SiteOrder(func(s *sql.Selector) {
		step := newUserStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SiteOrder) predicate.SiteOrder {
	return predicate.SiteOrder(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SiteOrder) predicate.SiteOrder {
	return predicate.SiteOrder(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SiteOrder) predicate.SiteOrder {
	return predicate.SiteOrder(sql.NotPredicates(p))
}
